  join public.branches b on b.slug = v.branch_slug
  join public.categories c on c.branch_id = b.id and c.slug = v.category_slug
on conflict (slug) do update set
  sku = excluded.sku, title = excluded.title, summary = excluded.summary, description = excluded.description,
  subdomain = excluded.subdomain, difficulty = excluded.difficulty, tech_stack = excluded.tech_stack, tags = excluded.tags,
  estimated_time = excluded.estimated_time, features = excluded.features, deliverables = excluded.deliverables,
  software_requirements = excluded.software_requirements, hardware_requirements = excluded.hardware_requirements, faq = excluded.faq,
  cover_image_path = excluded.cover_image_path, gallery_paths = excluded.gallery_paths, is_quote_only = excluded.is_quote_only
  where public.products.is_sample;

update public.products set
  is_sample = true,
  sku = coalesce(sku, 'PNX-DP-003'),
  subdomain = coalesce(subdomain, 'Network security'),
  estimated_time = coalesce(estimated_time, '3 to 4 weeks'),
  features = case when cardinality(features) = 0 then array['Preprocessing of network flow records', 'Training and comparison of several classifiers', 'Detection rate and false-alarm analysis', 'Confusion matrices and result charts', 'Discussion of limitations and improvements']::text[] else features end,
  deliverables = case when cardinality(deliverables) = 0 then array['Notebook and Python source code', 'Dataset notes and preprocessing steps', 'Project report', 'Presentation slides']::text[] else deliverables end,
  software_requirements = case when cardinality(software_requirements) = 0 then array['Python 3.10 or newer', 'Jupyter Notebook', 'scikit-learn, Pandas, Matplotlib']::text[] else software_requirements end,
  hardware_requirements = case when cardinality(hardware_requirements) = 0 then array['Any laptop with 8 GB RAM']::text[] else hardware_requirements end,
  faq = case when faq = '[]'::jsonb then '[{"q":"Is real network capture needed?","a":"No. The project works on recorded traffic data."},{"q":"Is this project verified?","a":"This is a sample listing, so there is no download yet. Real listings show exactly which files you receive."}]'::jsonb else faq end,
  cover_image_path = coalesce(cover_image_path, '/images/projects/network-intrusion-detection-ml.svg'),
  gallery_paths = case when cardinality(gallery_paths) = 0 then array['/images/projects/network-intrusion-detection-ml-tech.svg']::text[] else gallery_paths end
where slug = 'network-intrusion-detection-ml';

